import { createServer, createConnection } from 'node:net';
import { fork } from 'node:child_process';
import { once } from 'node:events';
if (process.argv[2] === 'server') {
  const server = createServer(socket => { socket.on('error',()=>{}); socket.end(); });
  await new Promise(resolve => server.listen({host:'127.0.0.1',port:0,backlog:Number(process.argv[3])},resolve));
  process.send({port:server.address().port});
  process.on('message',message=>{
    if(message==='block')process.send('blocked',()=>{const end=performance.now()+250;while(performance.now()<end){/* Controlled accept delay in this child only. */}});
    if(message==='stop')server.close(()=>process.disconnect());
  });
} else {
  const reports=[];
  for(const [backlog,concurrency] of [[511,64],[511,256],[8,256]]){
    const child=fork(new URL(import.meta.url),['server',String(backlog)],{stdio:['ignore','ignore','inherit','ipc']});
    const [{port}]=await once(child,'message');
    child.send('block');await once(child,'message');
    const errors=[],counts={};
    const start=performance.now();
    await Promise.all(Array.from({length:concurrency},()=>new Promise(resolve=>{
      const socket=createConnection({host:'127.0.0.1',port});let established=false;let finished=false;
      const done=(code)=>{if(finished)return;finished=true;clearTimeout(timer);counts[code]=(counts[code]??0)+1;socket.destroy();resolve();};
      const timer=setTimeout(()=>done('timeout'),2000);
      socket.once('connect',()=>{established=true;});
      socket.once('end',()=>done('connected'));socket.resume();
      socket.once('error',error=>{if(errors.length<5)errors.push({code:error.code,syscall:error.syscall,established});done(error.code??error.name);});
    })));
    child.send('stop');await once(child,'exit');
    reports.push({backlog,concurrency,durationMs:performance.now()-start,counts,errors});
  }
  console.log(JSON.stringify({node:process.version,platform:process.platform,reports},null,2));
}
